import express, { Request, Response, NextFunction } from 'express';
import sharp from 'sharp';
import crypto from 'crypto';
import { URL } from 'url';

const app = express();
app.use(express.json());

interface TenantConfig {
  id: string;
  allowedDomains: string[];
  callbackBase: string;
  hmacSecret: string;
}

const tenantStore: Map<string, TenantConfig> = new Map([
  ['tenant-a', { id: 'tenant-a', allowedDomains: ['cdn.tenant-a.com'], callbackBase: 'https://app.tenant-a.com', hmacSecret: 'secret-a-key-2024' }],
  ['tenant-b', { id: 'tenant-b', allowedDomains: ['cdn.tenant-b.com'], callbackBase: 'https://app.tenant-b.com', hmacSecret: 'secret-b-key-2024' }],
]);

function verifyTenantHmac(tenantId: string, payload: string, signature: string): boolean {
  const tenant = tenantStore.get(tenantId);
  if (!tenant) return false;
  const expected = crypto.createHmac('sha256', tenant.hmacSecret).update(payload).digest('hex');
  return crypto.timingSafeEqual(Buffer.from(expected, 'hex'), Buffer.from(signature, 'hex'));
}

function normalizeDomain(input: string): string {
  try {
    const parsed = new URL(input);
    return parsed.hostname.toLowerCase();
  } catch {
    return '';
  }
}

function buildCallbackUrl(tenant: TenantConfig, jobId: string, statusPath: string): string {
  const base = tenant.callbackBase;
  // Construct the callback URL by joining base with the status path
  // statusPath is expected to be like "/status/complete" or "/status/error"
  const normalized = statusPath.startsWith('/') ? statusPath : '/' + statusPath;
  return base + normalized;
}

function validateImageSource(tenantId: string, sourceUrl: string): boolean {
  const tenant = tenantStore.get(tenantId);
  if (!tenant) return false;
  const domain = normalizeDomain(sourceUrl);
  return tenant.allowedDomains.includes(domain);
}

async function processImage(sourceUrl: string, width: number, height: number): Promise<Buffer> {
  // Simulate fetching and processing
  const placeholder = Buffer.alloc(width * height * 4, 0);
  return sharp(placeholder, { raw: { width, height, channels: 4 } })
    .resize(width, height)
    .png()
    .toBuffer();
}

interface ProcessingJob {
  id: string;
  tenantId: string;
  sourceUrl: string;
  callbackUrl: string;
  status: 'pending' | 'complete' | 'error';
}

const jobQueue: Map<string, ProcessingJob> = new Map();

app.post('/api/v1/images/process', async (req: Request, res: Response) => {
  const { tenantId, sourceUrl, width, height, signature, callbackPath } = req.body;

  if (!tenantId || !sourceUrl || !width || !height || !signature) {
    return res.status(400).json({ error: 'Missing required fields' });
  }

  const payload = JSON.stringify({ tenantId, sourceUrl, width, height });
  if (!verifyTenantHmac(tenantId, payload, signature)) {
    return res.status(403).json({ error: 'Invalid signature' });
  }

  if (!validateImageSource(tenantId, sourceUrl)) {
    return res.status(403).json({ error: 'Source domain not allowed for tenant' });
  }

  const tenant = tenantStore.get(tenantId)!;
  const jobId = crypto.randomUUID();

  // callbackPath comes from the authenticated request body
  // It specifies where within the tenant's callback base to send the notification
  const statusPath = callbackPath || '/webhooks/image-status';
  const callbackUrl = buildCallbackUrl(tenant, jobId, statusPath);

  const job: ProcessingJob = {
    id: jobId,
    tenantId,
    sourceUrl,
    callbackUrl,
    status: 'pending'
  };
  jobQueue.set(jobId, job);

  // Process asynchronously
  setImmediate(async () => {
    try {
      await processImage(sourceUrl, width, height);
      job.status = 'complete';
    } catch {
      job.status = 'error';
    }
  });

  return res.status(202).json({ jobId, callbackUrl });
});

app.get('/api/v1/images/status/:jobId', (req: Request, res: Response) => {
  const job = jobQueue.get(req.params.jobId);
  if (!job) return res.status(404).json({ error: 'Job not found' });
  return res.json({ id: job.id, status: job.status, callbackUrl: job.callbackUrl });
});

// Redirect endpoint used by frontend to navigate to the callback after completion
app.get('/api/v1/images/callback-redirect/:jobId', (req: Request, res: Response) => {
  const job = jobQueue.get(req.params.jobId);
  if (!job) return res.status(404).json({ error: 'Job not found' });
  if (job.status !== 'complete') return res.status(400).json({ error: 'Job not complete' });

  // Redirect to the stored callback URL
  return res.redirect(302, job.callbackUrl);
});

export default app;
